fn csrf_valid(state: &AppState, submitted: &str) -> bool {
    constant_time_equal(submitted.as_bytes(), state.csrf_token.as_bytes())
}

fn render_quiz_list(_state: &AppState, quizzes: &[QuizSummary]) -> String {
    let mut content = String::from(
        "<div class=\"page-head\"><div><h1>Quizzes</h1><p class=\"meta\">Prepare the questions for your next talk.</p></div><a class=\"btn btn--pink\" href=\"/moderate/quizzes/new\">New quiz</a></div>",
    );
    if quizzes.is_empty() {
        content.push_str(
            "<div class=\"empty\">No quizzes yet. Create your first quiz to get started.</div>",
        );
    } else {
        content.push_str("<ul class=\"quiz-list\">");
        for quiz in quizzes {
            let title = escape_html(&quiz.title);
            content.push_str(&format!(
                "<li class=\"card quiz-list__item\"><a class=\"quiz-tile\" href=\"/moderate/quizzes/{}\"><h3>{title}</h3><div class=\"meta\">{} questions · {} active</div></a></li>",
                quiz.id, quiz.total, quiz.active
            ));
        }
        content.push_str("</ul>");
    }
    page("Quizzes", &content)
}

fn render_quiz_form(
    state: &AppState,
    quiz_id: Option<i64>,
    title: &str,
    errors: &[String],
) -> String {
    let editing = quiz_id.is_some();
    let escaped_title = escape_html(title);
    let mut content = String::new();
    content.push_str(if editing {
        "<div class=\"breadcrumbs\"><a href=\"/moderate\">← All quizzes</a></div><div class=\"page-head\"><h1>Settings</h1></div>"
    } else {
        "<div class=\"breadcrumbs\"><a href=\"/moderate\">← All quizzes</a></div><div class=\"page-head\"><h1>New quiz</h1></div>"
    });
    let action = quiz_id
        .map(|id| format!("/moderate/quizzes/{id}"))
        .unwrap_or_else(|| "/moderate/quizzes".to_owned());
    content.push_str(&format!(
        "<div class=\"card\"><form method=\"post\" action=\"{action}\"><input type=\"hidden\" name=\"csrf\" value=\"{}\"><div class=\"field\"><label for=\"title\">Title</label><input class=\"input\" id=\"title\" name=\"title\" type=\"text\" value=\"{escaped_title}\" required autocomplete=\"off\"></div>",
        escape_html(&state.csrf_token)
    ));
    content.push_str(&render_errors(errors));
    let cancel_path = quiz_id
        .map(|id| format!("/moderate/quizzes/{id}"))
        .unwrap_or_else(|| "/moderate".to_owned());
    content.push_str(&format!(
        "<div class=\"buttons\"><button class=\"btn btn--pink\" type=\"submit\">Save quiz</button><a class=\"btn btn--ghost\" href=\"{cancel_path}\">Cancel</a></div></form>"
    ));
    if let Some(id) = quiz_id {
        content.push_str(&format!(
            "<div class=\"buttons quiz-settings-actions\"><form method=\"post\" action=\"/moderate/quizzes/{id}/delete\" onsubmit=\"return confirm('Delete quiz?');\"><input type=\"hidden\" name=\"csrf\" value=\"{}\"><button class=\"btn btn--danger\" type=\"submit\">Delete quiz</button></form></div>",
            escape_html(&state.csrf_token)
        ));
    }
    content.push_str("</div>");
    page(if editing { "Settings" } else { "New quiz" }, &content)
}

fn render_quiz_page(state: &AppState, quiz: &Quiz) -> String {
    let title = escape_html(&quiz.title);
    let total = quiz.questions.len();
    let active_total = quiz
        .questions
        .iter()
        .filter(|question| question.active)
        .count();
    let mut content = format!(
        "<div class=\"breadcrumbs\"><a href=\"/moderate\">← All quizzes</a></div><div class=\"page-head\"><div><h1>{title}</h1><div class=\"meta mt-2\">{active_total} of {total} questions active · <a href=\"/moderate/quizzes/{}/settings\">Settings</a></div></div><div class=\"buttons\"><a class=\"btn btn--ghost\" href=\"/moderate/quizzes/{}/preview\">Preview</a></div></div>",
        quiz.id, quiz.id
    );
    content.push_str(&format!(
        "<section class=\"section mt-0\"><div class=\"section-head\"><h2>Questions</h2><a class=\"btn\" href=\"/moderate/quizzes/{}/questions/new\">Add question</a></div>",
        quiz.id
    ));
    if quiz.questions.is_empty() {
        content.push_str(
            "<div class=\"empty\">No questions yet. Add a question to build this quiz.</div>",
        );
    } else {
        content.push_str("<ol class=\"question-list\">");
        let mut active_number = 0;
        for (index, question) in quiz.questions.iter().enumerate() {
            if question.active {
                active_number += 1;
            }
            content.push_str(&render_question_item(
                state,
                quiz,
                question,
                index,
                active_number,
            ));
        }
        content.push_str("</ol>");
    }
    content.push_str("</section>");
    page(&quiz.title, &content)
}

